UPDATE spot s JOIN (
SELECT #{target.id} AS id, #{target.version} AS version
) AS judged ON judged.id = s.id AND judged.version = s.version SET s.protected_area_id = #{protectedAreaId,jdbcType=BIGINT}, s.park_warning = (#{protectedAreaId,jdbcType=BIGINT} IS NOT NULL), s.area_checked_at = #{now}, s.version = s.version + 1 WHERE s.type = 'BAKJI'
